</style><script>(()=>{const input=document.getElementById('input'),count=document.getElementById('count'),sep=document.getElementById('separator'),customWrap=document.getElementById('customWrap'),custom=document.getElementById('custom'),output=document.getElementById('output'),stats=document.getElementById('stats');sep.onchange=()=>customWrap.hidden=sep.value!=='custom';document.getElementById('repeat').onclick=()=>{const text=input.value;if(!text){output.value='';stats.textContent='Enter text first.';return}const n=Math.min(10000,Math.max(1,Number(count.value)||1));const s=sep.value==='newline'?'\n':sep.value==='space'?' ':sep.value==='comma'?', ':custom.value;output.value=Array(n).fill(text).join(s);stats.textContent=`${output.value.length.toLocaleString()} characters · ${n.toLocaleString()} repetitions`};document.getElementById('copy').onclick=async()=>{if(!output.value)return;await navigator.clipboard.writeText(output.value);document.getElementById('copy').textContent='Copied';setTimeout(()=>document.getElementById('copy').textContent='Copy Output',900)};document.getElementById('clear').onclick=()=>{input.value='';output.value='';stats.textContent='0 characters'}})();</script>
